  "enrichment_proposal": {
    "project_revision": "sha256:582dd4655bec11389717111fbfc9b7b0331640e409f3158e9915ab5020098900",
    "operations": [
      {
        "changeKind": "new_cube",
        "summary": "Create orders_analytics cube with revenue measures and order dimensions",
        "relative_sink": "cubes/orders_analytics/metadata.yml",
        "recommended_yaml": "name: orders_analytics\nbase_object: orders\nmeasures:\n  - name: total_order_count\n    expression: COUNT(order_id)\n    type: BIGINT\n  - name: total_revenue\n    expression: SUM(amount)\n    type: DOUBLE\ndimensions:\n  - name: order_status\n    expression: status\n    type: TEXT\ntime_dimensions:\n  - name: order_date\n    expression: order_date\n    type: DATE\nproperties:\n  description: Analytical cube for order revenue metrics and dimensions\n",
